/**
 * Centralizes the event rules that control time-of-day and weather changes.
 *
 * @version 2022.03.02
 */
public class SimulationRulesEngine
{
    private static final int DAY_NIGHT_CYCLE_LENGTH = 80;
    private static final int DAYLIGHT_DURATION = 55;
    private static final int WEATHER_CHANGE_INTERVAL = 450;

    private final Weather weather;

    public SimulationRulesEngine(Weather weather)
    {
        this.weather = weather;
    }

    /**
     * Apply step-based environment events such as periodic weather changes.
     *
     * @param step The simulation step being executed.
     */
    public void applyStepEvents(int step)
    {
        if (step % WEATHER_CHANGE_INTERVAL == 0) {
            weather.changeWeather();
        }
    }

    /**
     * Determine whether an organism should act during the current step.
     *
     * @param organism The organism being considered.
     * @param step The current simulation step.
     * @return True if the organism is active this step.
     */
    public boolean canAct(Organism organism, int step)
    {
        return getTimeOfDay(step).matches(organism.isDiurnal());
    }

    /**
     * Return the time-of-day phase for the given step.
     *
     * @param step The current simulation step.
     * @return The time-of-day phase.
     */
    public TimeOfDay getTimeOfDay(int step)
    {
        if (step % DAY_NIGHT_CYCLE_LENGTH <= DAYLIGHT_DURATION) {
            return TimeOfDay.DAY;
        }
        return TimeOfDay.NIGHT;
    }

    /**
     * Return the weather label for the current environment.
     *
     * @return The current weather name.
     */
    public String getCurrentWeather()
    {
        return weather.getCurrentWeather();
    }

    /**
     * Set the weather explicitly.
     *
     * @param weatherName The new weather to apply.
     */
    public void setWeather(String weatherName)
    {
        weather.setWeather(weatherName);
    }

    /**
     * Reset the event rules to their initial state.
     */
    public void reset()
    {
        weather.resetWeather();
    }
}

/**
 * Immutable query object describing the current simulation state.
 *
 * @version 2022.03.02
 */
public class SimulationState
{
    private final int step;
    private final FieldSnapshot fieldSnapshot;
    private final String currentWeather;
    private final TimeOfDay timeOfDay;
    private final boolean viable;

    public SimulationState(int step, FieldSnapshot fieldSnapshot,
                           String currentWeather, TimeOfDay timeOfDay,
                           boolean viable)
    {
        this.step = step;
        this.fieldSnapshot = fieldSnapshot;
        this.currentWeather = currentWeather;
        this.timeOfDay = timeOfDay;
        this.viable = viable;
    }

    public int getStep()
    {
        return step;
    }

    public FieldSnapshot getFieldSnapshot()
    {
        return fieldSnapshot;
    }

    public String getCurrentWeather()
    {
        return currentWeather;
    }

    public TimeOfDay getTimeOfDay()
    {
        return timeOfDay;
    }

    public boolean isViable()
    {
        return viable;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A class representing all shared characteristics of organisms.
 * Organisms have an age, field and a location in the field.
 * All organisms are able to act and breed.
 *
 * @version 2022.03.02
 */
public abstract class Organism implements FieldOccupant
{
    // Shared lifecycle settings for this organism's species.
    private final OrganismAttributes attributes;
    // The organism's age
    private int age;
    // Whether the organism is alive or not.
    private boolean alive;
    // The organism's field.
    private Field field;
    // The organism's position in the field.
    private Location location;

    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for objects of class Organism
     */
    public Organism(boolean randomAge, Field field, Location location,
                    OrganismAttributes attributes)
    {
        this.attributes = attributes;
        age = 0;
        if (randomAge) {
            age = rand.nextInt(attributes.getMaxAge());
        }
        alive = true;
        this.field = field;
        setLocation(location);
    }

    // Accessor and mutator methods

    /**
     * Return this organism's species.
     *
     * @return The organism species.
     */
    public Species getSpecies()
    {
        return attributes.getSpecies();
    }

    /**
     * Return whether the organism is diurnal or nocturnal.
     *
     * @return True if the organism is diurnal.
     */
    public boolean isDiurnal()
    {
        return attributes.isDiurnal();
    }

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Returns the random object of the organism
     * 
     * @return Random object of the organism
     */
    protected Random getRand() {
        return rand;
    }

    /**
     * Returns the age of the organism
     * 
     * @return The organism's age
     */
    public int getAge()
    {
        return age;
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    // Functional methods

    /**
     * Make this organism act for a single simulation step.
     *
     * @param newOrganisms A list to receive newly born organisms.
     */
    public final void act(List<Organism> newOrganisms)
    {
        for(OrganismActionCommand action : attributes.getActionCommands()) {
            if(!isAlive()) {
                break;
            }
            action.execute(this, newOrganisms);
        }
    }

    /**
     * Determines the amount of newborn a specific organism will produce
     * 
     * @return the number of newborn produced by the organism
     */
    protected int breed()
    {
        int births = 0;
        if(attributes.getBreedingStrategy().canBreed(this)
           && getRand().nextDouble() <= attributes.getBreedingProbability()) {
            births = getRand().nextInt(attributes.getMaxLitterSize()) + 1;
        }
        return births;
    }

    /**
     * Adds newborn organisms to a list
     */
    protected void giveBirth(List<Organism> newOrganisms)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Organism young = attributes.create(false, field, loc);
            newOrganisms.add(young);
        }
    }

    /**
     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
     */
    protected void incrementAge()
    {
        age++;
        if (age > attributes.getMaxAge())
        {
            setDead();
        }
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the shared attributes for this organism.
     */
    final OrganismAttributes getAttributes()
    {
        return attributes;
    }

    /**
     * Move the organism if its species requires relocation this step.
     */
    protected void relocate()
    {
        RelocationStrategy relocationStrategy = attributes.getRelocationStrategy();
        Location newLocation = relocationStrategy.findNextLocation(this);
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else if(relocationStrategy.diesWhenBlocked()) {
            setDead();
        }
    }
}

/**
 * This class formats field snapshot data into user-facing statistics.
 * 
 * @version 2022.03.02
 */
public class FieldStats
{
    /**
     * Get details of what is in the current simulation state.
     * @return A string describing the visible field state.
     */
    public String getPopulationDetails(SimulationState state)
    {
        FieldSnapshot snapshot = state.getFieldSnapshot();
        StringBuffer buffer = new StringBuffer();
        for(Species species : snapshot.getPresentSpecies()) {
            buffer.append(species.getDisplayName());
            buffer.append(": ");
            buffer.append(snapshot.getPopulationCount(species));
            buffer.append(' ');
        }
        buffer.append("Weather: " + state.getCurrentWeather());
        buffer.append(" Time: " + state.getTimeOfDay().getDisplayName());
        return buffer.toString();
    }
}

