 6	/**
 7	 * Synchronous in-process event bus for simulation lifecycle events.
 8	 *
 9	 * @version 2022.03.02
10	 */
11	public class SimulationEventBus
12	{
13	    private final Map<Class<? extends SimulationEvent>,
14	                     List<SimulationEventListener>> listeners;
15	
16	    public SimulationEventBus()
17	    {
18	        listeners = new LinkedHashMap<>();
19	    }
20	
21	    public void subscribe(Class<? extends SimulationEvent> eventType,
22	                          SimulationEventListener listener)
23	    {
24	        List<SimulationEventListener> subscribed = listeners.get(eventType);
25	        if(subscribed == null) {
26	            subscribed = new ArrayList<>();
27	            listeners.put(eventType, subscribed);
28	        }
29	        subscribed.add(listener);
30	    }
31	
32	    public void publish(SimulationEvent event)
33	    {
34	        for(Map.Entry<Class<? extends SimulationEvent>,
35	                      List<SimulationEventListener>> entry : listeners.entrySet()) {
36	            if(entry.getKey().isInstance(event)) {
37	                notifyListeners(entry.getValue(), event);
38	            }
39	        }
40	    }
41	
42	    private void notifyListeners(List<SimulationEventListener> subscribed,
43	                                 SimulationEvent event)
44	    {
45	        List<SimulationEventListener> listenersSnapshot =
46	            new ArrayList<>(subscribed);
47	        for(SimulationEventListener listener : listenersSnapshot) {
48	            listener.onEvent(event);
49	        }
50	    }
51	}

