  1	/**
  2	 * Centralizes the event rules that control time-of-day and weather changes.
  3	 *
  4	 * @version 2022.03.02
  5	 */
  6	public class SimulationRulesEngine
  7	{
  8	    private static final int DAY_NIGHT_CYCLE_LENGTH = 80;
  9	    private static final int DAYLIGHT_DURATION = 55;
 10	    private static final int WEATHER_CHANGE_INTERVAL = 450;
 11	
 12	    private final Weather weather;
 13	    private final SimulationEventBus eventBus;
 14	    private TimeOfDay currentTimeOfDay;
 15	
 16	    public SimulationRulesEngine(Weather weather, SimulationEventBus eventBus)
 17	    {
 18	        this.weather = weather;
 19	        this.eventBus = eventBus;
 20	        currentTimeOfDay = null;
 21	        registerListeners();
 22	    }
 23	
 24	    /**
 25	     * Register bus listeners for environment changes.
 26	     */
 27	    private void registerListeners()
 28	    {
 29	        eventBus.subscribe(SimulationStepStartedEvent.class,
 30	                           new SimulationEventListener() {
 31	                               public void onEvent(SimulationEvent event)
 32	                               {
 33	                                   SimulationStepStartedEvent started =
 34	                                       (SimulationStepStartedEvent) event;
 35	                                   handleStepStarted(started.getStep());
 36	                               }
 37	                           });
 38	        eventBus.subscribe(SimulationResetRequestedEvent.class,
 39	                           new SimulationEventListener() {
 40	                               public void onEvent(SimulationEvent event)
 41	                               {
 42	                                   reset();
 43	                               }
 44	                           });
 45	        eventBus.subscribe(WeatherChangeRequestedEvent.class,
 46	                           new SimulationEventListener() {
 47	                               public void onEvent(SimulationEvent event)
 48	                               {
 49	                                   WeatherChangeRequestedEvent request =
 50	                                       (WeatherChangeRequestedEvent) event;
 51	                                   setWeather(request.getWeatherName());
 52	                               }
 53	                           });
 54	    }
 55	
 56	    /**
 57	     * Apply step-based environment events such as periodic weather changes.
 58	     *
 59	     * @param step The simulation step being executed.
 60	     */
 61	    public void handleStepStarted(int step)
 62	    {
 63	        updateTimeOfDay(step);
 64	        if(step % WEATHER_CHANGE_INTERVAL == 0) {
 65	            String previousWeather = weather.getCurrentWeather();
 66	            weather.changeWeather();
 67	            publishWeatherChanged(previousWeather, weather.getCurrentWeather());
 68	        }
 69	    }
 70	
 71	    /**
 72	     * Determine whether an organism should act during the current step.
 73	     *
 74	     * @param organism The organism being considered.
 75	     * @param step The current simulation step.
 76	     * @return True if the organism is active this step.
 77	     */
 78	    public boolean canAct(Organism organism, int step)
 79	    {
 80	        return getTimeOfDay(step).matches(organism.isDiurnal());
 81	    }
 82	
 83	    /**
 84	     * Return the time-of-day phase for the given step.
 85	     *
 86	     * @param step The current simulation step.
 87	     * @return The time-of-day phase.
 88	     */
 89	    public TimeOfDay getTimeOfDay(int step)
 90	    {
 91	        if (step % DAY_NIGHT_CYCLE_LENGTH <= DAYLIGHT_DURATION) {
 92	            return TimeOfDay.DAY;
 93	        }
 94	        return TimeOfDay.NIGHT;
 95	    }
 96	
 97	    /**
 98	     * Return the weather label for the current environment.
 99	     *
100	     * @return The current weather name.
101	     */
102	    public String getCurrentWeather()
103	    {
104	        return weather.getCurrentWeather();
105	    }
106	
107	    /**
108	     * Set the weather explicitly.
109	     *
110	     * @param weatherName The new weather to apply.
111	     */
112	    public void setWeather(String weatherName)
113	    {
114	        String previousWeather = weather.getCurrentWeather();
115	        weather.setWeather(weatherName);
116	        publishWeatherChanged(previousWeather, weatherName);
117	    }
118	
119	    /**
120	     * Reset the event rules to their initial state.
121	     */
122	    public void reset()
123	    {
124	        currentTimeOfDay = null;
125	        updateTimeOfDay(0);
126	        String previousWeather = weather.getCurrentWeather();
127	        weather.resetWeather();
128	        publishWeatherChanged(previousWeather, weather.getCurrentWeather());
129	    }
130	
131	    private void updateTimeOfDay(int step)
132	    {
133	        TimeOfDay nextTimeOfDay = getTimeOfDay(step);
134	        if(currentTimeOfDay != nextTimeOfDay) {
135	            TimeOfDay previousTimeOfDay = currentTimeOfDay;
136	            currentTimeOfDay = nextTimeOfDay;
137	            if(previousTimeOfDay != null) {
138	                eventBus.publish(new TimeOfDayChangedEvent(step, previousTimeOfDay,
139	                                                           nextTimeOfDay));
140	            }
141	        }
142	    }
143	
144	    private void publishWeatherChanged(String previousWeather, String nextWeather)
145	    {
146	        if(previousWeather == null || !previousWeather.equals(nextWeather)) {
147	            eventBus.publish(new WeatherChangedEvent(previousWeather, nextWeather));
148	        }
149	    }
150	}

