  4	/**
  5	 * A class representing all shared characteristics of organisms.
  6	 * Organisms have an age, field and a location in the field.
  7	 * All organisms are able to act and breed.
  8	 *
  9	 * @version 2022.03.02
 10	 */
 11	public abstract class Organism implements FieldOccupant
 12	{
 13	    // Shared lifecycle settings for this organism's species.
 14	    private final OrganismAttributes attributes;
 15	    // Event bus used to publish lifecycle changes.
 16	    private final SimulationEventBus eventBus;
 17	    // The organism's age
 18	    private int age;
 19	    // Whether the organism is alive or not.
 20	    private boolean alive;
 21	    // The organism's field.
 22	    private Field field;
 23	    // The organism's position in the field.
 24	    private Location location;
 25	    
 26	    // A shared random number generator to control breeding.
 27	    private static final Random rand = Randomizer.getRandom();
 28	    
 29	    /**
 30	     * Constructor for objects of class Organism
 31	     */
 32	    public Organism(boolean randomAge, Field field, Location location,
 33	                    OrganismAttributes attributes, SimulationEventBus eventBus)
 34	    {
 35	        this.attributes = attributes;
 36	        this.eventBus = eventBus;
 37	        age = 0;
 38	        if (randomAge) {
 39	            age = rand.nextInt(attributes.getMaxAge());
 40	        }
 41	        alive = true;
 42	        this.field = field;
 43	        setLocation(location);
 44	    }
 45	    
 46	    // Accessor and mutator methods
 47	
 48	    /**
 49	     * Return this organism's species.
 50	     *
 51	     * @return The organism species.
 52	     */
 53	    public Species getSpecies()
 54	    {
 55	        return attributes.getSpecies();
 56	    }
 57	
 58	    /**
 59	     * Return whether the organism is diurnal or nocturnal.
 60	     *
 61	     * @return True if the organism is diurnal.
 62	     */
 63	    public boolean isDiurnal()
 64	    {
 65	        return attributes.isDiurnal();
 66	    }
 67	    
 68	    /**
 69	     * Return the organism's location.
 70	     * @return The organism's location.
 71	     */
 72	    protected Location getLocation()
 73	    {
 74	        return location;
 75	    }
 76	    
 77	    /**
 78	     * Return the organism's field.
 79	     * @return The organism's field.
 80	     */
 81	    protected Field getField()
 82	    {
 83	        return field;
 84	    }
 85	    
 86	    /**
 87	     * Returns the random object of the organism
 88	     * 
 89	     * @return Random object of the organism
 90	     */
 91	    protected Random getRand() {
 92	        return rand;
 93	    }
 94	    
 95	    /**
 96	     * Returns the age of the organism
 97	     * 
 98	     * @return The organism's age
 99	     */
100	    public int getAge()
101	    {
102	        return age;
103	    }
104	    
105	    /**
106	     * Check whether the organism is alive or not.
107	     * @return true if the organism is still alive.
108	     */
109	    public boolean isAlive()
110	    {
111	        return alive;
112	    }
113	    
114	    // Functional methods
115	
116	    /**
117	     * Make this organism act for a single simulation step.
118	     *
119	     * @param newOrganisms A list to receive newly born organisms.
120	     */
121	    public final void act(List<Organism> newOrganisms)
122	    {
123	        for(OrganismActionCommand action : attributes.getActionCommands()) {
124	            if(!isAlive()) {
125	                break;
126	            }
127	            action.execute(this, newOrganisms);
128	        }
129	    }
130	    
131	    /**
132	     * Determines the amount of newborn a specific organism will produce
133	     * 
134	     * @return the number of newborn produced by the organism
135	     */
136	    protected int breed()
137	    {
138	        int births = 0;
139	        if(attributes.getBreedingStrategy().canBreed(this)
140	           && getRand().nextDouble() <= attributes.getBreedingProbability()) {
141	            births = getRand().nextInt(attributes.getMaxLitterSize()) + 1;
142	        }
143	        return births;
144	    }
145	    
146	    /**
147	     * Adds newborn organisms to a list
148	     */
149	    protected void giveBirth(List<Organism> newOrganisms)
150	    {
151	        // New rabbits are born into adjacent locations.
152	        // Get a list of adjacent free locations.
153	        Field field = getField();
154	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
155	        int births = breed();
156	        for(int b = 0; b < births && free.size() > 0; b++) {
157	            Location loc = free.remove(0);
158	            Organism young = attributes.create(false, field, loc, eventBus);
159	            newOrganisms.add(young);
160	            eventBus.publish(new OrganismBornEvent(young.getSpecies(), loc,
161	                                                   BirthSource.REPRODUCTION));
162	        }
163	    }
164	    
165	    /**
166	     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
167	     */
168	    protected void incrementAge()
169	    {
170	        age++;
171	        if (age > attributes.getMaxAge())
172	        {
173	            setDead();
174	        }
175	    }
176	    
177	    /**
178	     * Indicate that the organism is no longer alive.
179	     * It is removed from the field.
180	     */
181	    protected void setDead()
182	    {
183	        Species species = getSpecies();
184	        Location previousLocation = location;
185	        alive = false;
186	        if(location != null) {
187	            field.clear(location);
188	            location = null;
189	            field = null;
190	        }
191	        if(previousLocation != null) {
192	            eventBus.publish(new OrganismDiedEvent(species, previousLocation));
193	        }
194	    }
195	
196	    /**
197	     * Place the organism at the new location in the given field.
198	     * @param newLocation The organism's new location.
199	     */
200	    protected void setLocation(Location newLocation)
201	    {
202	        if(location != null) {
203	            field.clear(location);
204	        }
205	        location = newLocation;
206	        field.place(this, newLocation);
207	    }
208	
209	    /**
210	     * Return the shared attributes for this organism.
211	     */
212	    final OrganismAttributes getAttributes()
213	    {
214	        return attributes;
215	    }
216	
217	    /**
218	     * Move the organism if its species requires relocation this step.
219	     */
220	    protected void relocate()
221	    {
222	        RelocationStrategy relocationStrategy = attributes.getRelocationStrategy();
223	        Location newLocation = relocationStrategy.findNextLocation(this);
224	        if(newLocation != null) {
225	            setLocation(newLocation);
226	        }
227	        else if(relocationStrategy.diesWhenBlocked()) {
228	            setDead();
229	        }
230	    }
231	}

