168	    
169	    /**
170	     * Run the simulation from its current state for the given number of steps.
171	     * Stop before the given number of steps if it ceases to be viable.
172	     * @param numSteps The number of steps to run for.
173	     */
174	    public void simulate(int numSteps)
175	    {
176	        for(int step = 1; step <= numSteps && isViable(); step++) {
177	            simulateOneStep();
178	            //delay(60);   // uncomment this to run more slowly
179	        }
180	    }
181	    
182	    /**
183	     * Run the simulation from its current state for a single step.
184	     * Iterate over the whole field updating the state of each
185	     * fox and rabbit.
186	     */
187	    public void simulateOneStep()
188	    {
189	        step++;
190	        eventBus.publish(new SimulationStepStartedEvent(step));
191	        // Provide space for newborn animals.
192	        List<Organism> newOrganisms = new ArrayList<>();        
193	        // Let all rabbits act.
194	        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
195	            Organism organism = it.next();
196	            
197	            if (rules.canAct(organism, step)) {
198	                organism.act(newOrganisms);
199	            }
200	            if(! organism.isAlive()) {
201	                it.remove();
202	            }
203	        }
204	                   
205	        // Add the newly born organisms to the main lists.
206	        organisms.addAll(newOrganisms);
207	        eventBus.publish(new SimulationStepCompletedEvent(getState()));
208	    }
209	        
210	    /**
211	     * Reset the simulation to a starting position.
212	     */
213	    public void reset()
214	    {
215	        step = 0;
216	        organisms.clear();
217	        populate();
218	        eventBus.publish(new SimulationResetRequestedEvent());
219	        eventBus.publish(new SimulationResetCompletedEvent(getState()));
220	    }
221	    
222	    /**
223	     * Randomly populate the field with foxes and rabbits.
224	     */
225	    private void populate()
226	    {
227	        Random rand = Randomizer.getRandom();
228	        field.clear();
229	        for(int row = 0; row < field.getDepth(); row++) {
230	            for(int col = 0; col < field.getWidth(); col++) {
231	                seedLocation(rand, new Location(row, col));
232	            }
233	        }
234	    }
235	    
236	    /**
237	     * Pause for a given time.
238	     * @param millisec  The time to pause for, in milliseconds
239	     */
240	    private void delay(int millisec)
241	    {
242	        try {
243	            Thread.sleep(millisec);
244	        }
245	        catch (InterruptedException ie) {
246	            // wake up
247	        }
248	    }
249	    
250	    /**
251	     * Populate one location by selecting the first species whose creation
252	     * probability passes. Each cell can contain at most one organism.
253	     */
254	    private void seedLocation(Random rand, Location location)
255	    {
256	        if(seedFromRules(rand, location, primaryPopulationRules)) {
257	            return;
258	        }
259	        seedFromRules(rand, location, secondaryPopulationRules);
260	    }
261	
262	    /**
263	     * Try each creation rule in sequence until one organism is created.
264	     *
265	     * @return True if a species was placed at the location.
266	     */
267	    private boolean seedFromRules(Random rand, Location location, PopulationRule[] rules)
268	    {
269	        for(PopulationRule rule : rules) {
270	            if(rand.nextDouble() <= rule.getCreationProbability()) {
271	                Organism organism = rule.create(field, location, eventBus);
272	                organisms.add(organism);
273	                eventBus.publish(new OrganismBornEvent(organism.getSpecies(),
274	                                                       location,
275	                                                       BirthSource.INITIAL_POPULATION));
276	                return true;
277	            }
278	        }
279	        return false;
280	    }
281	}

