102	    public void showStatus(SimulationState state)
103	    {
104	        if(!isVisible()) {
105	            setVisible(true);
106	        }
107	
108	        FieldSnapshot snapshot = state.getFieldSnapshot();
109	
110	        stepLabel.setText(STEP_PREFIX + state.getStep());
111	        fieldView.preparePaint();
112	
113	        for(int row = 0; row < snapshot.getDepth(); row++) {
114	            for(int col = 0; col < snapshot.getWidth(); col++) {
115	                Species species = snapshot.getSpeciesAt(row, col);
116	                if(species != null) {
117	                    fieldView.drawMark(col, row, getColor(species));
118	                }
119	                else {
120	                    fieldView.drawMark(col, row, EMPTY_COLOR);
121	                }
122	            }
123	        }
124	
125	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(state));
126	        fieldView.repaint();
127	    }
