150	    private class FieldView extends JPanel
151	    {
152	        private final int GRID_VIEW_SCALING_FACTOR = 6;
153	
154	        private int gridWidth, gridHeight;
155	        private int xScale, yScale;
156	        private Dimension size;
157	        private Graphics g;
158	        private Image fieldImage;
159	
160	        public FieldView(int height, int width)
161	        {
162	            gridHeight = height;
163	            gridWidth = width;
164	            size = new Dimension(0, 0);
165	        }
166	
167	        public Dimension getPreferredSize()
168	        {
169	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
170	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
171	        }
172	
173	        public void preparePaint()
174	        {
175	            if(! size.equals(getSize())) {
176	                size = getSize();
177	                fieldImage = fieldView.createImage(size.width, size.height);
178	                g = fieldImage.getGraphics();
179	
180	                xScale = size.width / gridWidth;
181	                if(xScale < 1) {
182	                    xScale = GRID_VIEW_SCALING_FACTOR;
183	                }
184	                yScale = size.height / gridHeight;
185	                if(yScale < 1) {
186	                    yScale = GRID_VIEW_SCALING_FACTOR;
187	                }
188	            }
189	        }
190	
191	        public void drawMark(int x, int y, Color color)
192	        {
193	            g.setColor(color);
194	            g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
195	        }
196	
197	        public void paintComponent(Graphics g)
198	        {
199	            if(fieldImage != null) {
200	                Dimension currentSize = getSize();
201	                if(size.equals(currentSize)) {
202	                    g.drawImage(fieldImage, 0, 0, null);
203	                }
204	                else {
205	                    g.drawImage(fieldImage, 0, 0,
206	                                currentSize.width, currentSize.height, null);
207	                }
208	            }
209	        }
210	    }
